mode_conversion_factor.py:
"""Equivalent rating factors for converting between freight pricing modes.

Operations normalizes customer rates across truckload, LTL, drayage, and flatbed so
analytics can compare bids on a common basis. The conversion here returns a factor
that multiplies the source mode's amount into an equivalent target-mode amount.

Business rules:
- Base factors are configured per source/target mode pair.
- Weight, distance, and stop count slightly adjust the factor within narrow bands.
- Residential delivery only affects LTL destinations.
- Hazmat applies a small uplift except on drayage, where local port tariffs already
  include most handling.
- Cross-border moves add friction on truckload and flatbed conversions.
- Very short drayage moves under 25 miles use a local minimum factor.
- Flatbed with over-dimensional freight adds an extra uplift.
- Final factors are rounded half up to four decimals and never below 0.2500.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

FOUR_PLACES = Decimal("0.0001")
MIN_FACTOR = Decimal("0.2500")

_BASE_FACTORS = {
    ("truckload", "ltl"): Decimal("1.1800"),
    ("truckload", "drayage"): Decimal("0.7600"),
    ("truckload", "flatbed"): Decimal("1.1200"),
    ("ltl", "truckload"): Decimal("0.8501"),
    ("ltl", "drayage"): Decimal("0.6400"),
    ("ltl", "flatbed"): Decimal("1.0500"),
    ("drayage", "truckload"): Decimal("1.3100"),
    ("drayage", "ltl"): Decimal("1.4200"),
    ("drayage", "flatbed"): Decimal("1.2700"),
    ("flatbed", "truckload"): Decimal("0.9100"),
    ("flatbed", "ltl"): Decimal("1.0900"),
    ("flatbed", "drayage"): Decimal("0.7000"),
}


@dataclass(frozen=True)
class ConversionRequest:
    source_mode: str
    target_mode: str
    weight_lb: int
    distance_miles: int
    stops: int = 2
    residential: bool = False
    hazmat: bool = False
    cross_border: bool = False
    overdimensional: bool = False


@dataclass(frozen=True)
class ConversionTerms:
    heavy_weight_threshold_lb: int = 30000
    long_haul_threshold_miles: int = 1000
    stop_surcharge_per_extra_stop: Decimal = Decimal("0.0150")
    max_stop_surcharge: Decimal = Decimal("0.0600")
    short_drayage_max_miles: int = 25
    short_drayage_factor: Decimal = Decimal("0.5800")


def _validate(req: ConversionRequest) -> None:
    modes = {"truckload", "ltl", "drayage", "flatbed"}
    if req.source_mode not in modes or req.target_mode not in modes:
        raise ValueError("unsupported mode")
    if req.source_mode == req.target_mode:
        raise ValueError("source and target modes must differ")
    if req.weight_lb <= 0 or req.distance_miles <= 0:
        raise ValueError("weight and distance must be positive")
    if req.stops < 1:
        raise ValueError("stops must be at least 1")


def _base_factor(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.source_mode == "drayage" and req.distance_miles <= terms.short_drayage_max_miles:
        if req.target_mode == "truckload":
            return terms.short_drayage_factor
    return _BASE_FACTORS[(req.source_mode, req.target_mode)]


def _weight_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.target_mode == "ltl":
        if req.weight_lb < 5000:
            return Decimal("0.0800")
        if req.weight_lb > 20000:
            return Decimal("-0.0500")
    if req.weight_lb >= terms.heavy_weight_threshold_lb and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("0.0400")
    return Decimal("0.0000")


def _distance_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.distance_miles < 50 and req.target_mode == "ltl":
        return Decimal("0.0600")
    if req.distance_miles >= terms.long_haul_threshold_miles and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("-0.0300")
    return Decimal("0.0000")


def _accessorial_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    adj = Decimal("0.0000")
    extra_stops = max(req.stops - 2, 0)
    stop_adj = terms.stop_surcharge_per_extra_stop * extra_stops
    if stop_adj > terms.max_stop_surcharge:
        stop_adj = terms.max_stop_surcharge
    adj += stop_adj
    if req.residential and req.target_mode == "ltl":
        adj += Decimal("0.0450")
    if req.hazmat:
        adj += Decimal("0.0100") if req.target_mode == "drayage" else Decimal("0.0250")
    if req.cross_border and req.target_mode in {"truckload", "flatbed"}:
        adj += Decimal("0.0350")
    if req.overdimensional and req.target_mode == "flatbed":
        adj += Decimal("0.0700")
    return adj


def calculate_mode_conversion_factor(
    req: ConversionRequest, terms: ConversionTerms = ConversionTerms()
) -> Decimal:
    """Return the equivalent factor from source mode pricing to target mode pricing."""
    _validate(req)
    factor = _base_factor(req, terms)
    factor += _weight_adjustment(req, terms)
    factor += _distance_adjustment(req, terms)
    factor += _accessorial_adjustment(req, terms)
    if factor <= MIN_FACTOR:
        factor = MIN_FACTOR
    return factor.quantize(FOUR_PLACES, rounding=ROUND_HALF_UP)

payment_terms_due_date.py:
"""Invoice payment terms due dates for carrier settlements and customer billing.

The billing platform uses one rules engine for customer invoices and carrier self-bills.
This module computes the contractual due date from an issue date plus term details.
Standard net terms add calendar days to the issue date. Some contracts use end-of-
month handling: if issued on or after a threshold day, the due date is based on the
last day of the following month instead of simple day addition. After the base date is
chosen, non-business-day rolling applies. Weekend and listed holiday dates can roll
forward to the next business day or backward to the previous business day; a contract
may also specify no rolling. A grace period may then be added in business days.
"""

from dataclasses import dataclass, field
from datetime import date, timedelta


@dataclass(frozen=True)
class PaymentTermsInput:
    issue_date: date
    terms_days: int
    eom_threshold_day: int | None = None
    roll_rule: str = "forward"
    holiday_dates: frozenset[date] = field(default_factory=frozenset)
    grace_business_days: int = 0


_VALID_ROLL_RULES = {"forward", "backward", "none"}


def _validate(terms: PaymentTermsInput) -> None:
    if terms.terms_days < 0:
        raise ValueError("terms_days must be >= 0")
    if terms.grace_business_days < 0:
        raise ValueError("grace_business_days must be >= 0")
    if terms.roll_rule not in _VALID_ROLL_RULES:
        raise ValueError(f"unsupported roll_rule {terms.roll_rule!r}")
    if terms.eom_threshold_day is not None and not 1 <= terms.eom_threshold_day <= 31:
        raise ValueError("eom_threshold_day must be between 1 and 31")


def _last_day_of_month(day: date) -> date:
    if day.month == 12:
        return date(day.year, 12, 31)
    return date(day.year, day.month + 1, 1) - timedelta(days=1)


def _is_business_day(day: date, holidays: frozenset[date]) -> bool:
    return day.weekday() < 5 and day not in holidays


def _roll(day: date, rule: str, holidays: frozenset[date]) -> date:
    if rule == "none" or _is_business_day(day, holidays):
        return day
    step = 1 if rule == "forward" else -2
    current = day
    while not _is_business_day(current, holidays):
        current += timedelta(days=step)
    return current


def _add_business_days(day: date, business_days: int, holidays: frozenset[date]) -> date:
    current = day
    added = 0
    while added < business_days:
        current += timedelta(days=1)
        if _is_business_day(current, holidays):
            added += 1
    return current


def _base_due_date(terms: PaymentTermsInput) -> date:
    if terms.eom_threshold_day is None or terms.issue_date.day < terms.eom_threshold_day:
        return terms.issue_date + timedelta(days=terms.terms_days)

    issue = terms.issue_date
    if issue.month == 12:
        first_of_next_month = date(issue.year + 1, 1, 1)
    else:
        first_of_next_month = date(issue.year, issue.month + 1, 1)
    return _last_day_of_month(first_of_next_month) + timedelta(days=terms.terms_days)


def calculate_payment_terms_due_date(terms: PaymentTermsInput) -> date:
    """Return the contractual due date after EOM logic, rolling, and grace days.

    EOM logic applies only when ``eom_threshold_day`` is set and the issue day is on
    or after the threshold. In that case, the base date is the last day of the next
    month plus ``terms_days``. The base date is then rolled per ``roll_rule`` if it
    lands on a weekend or listed holiday. Finally, ``grace_business_days`` are added
    as business days.

    >>> calculate_payment_terms_due_date(PaymentTermsInput(issue_date=date(2026, 1, 10), terms_days=30))
    datetime.date(2026, 2, 9)
    """
    _validate(terms)
    base = _base_due_date(terms)
    rolled = _roll(base, terms.roll_rule, terms.holiday_dates)
    return _add_business_days(rolled, terms.grace_business_days, terms.holiday_dates)

tests/test_proration.py:
from decimal import Decimal

import pytest

from proration import Order, prorate_charge


def orders(*weights):
    return [Order(f"ORD-{i + 1}", weight) for i, weight in enumerate(weights)]


def test_exact_shares_need_no_adjustment():
    split = prorate_charge(Decimal("100.00"), orders(2100, 4950, 2950))
    assert split == {"ORD-1": Decimal("21.00"), "ORD-2": Decimal("49.50"), "ORD-3": Decimal("29.50")}


def test_even_split_ties_go_to_the_earlier_order():
    split = prorate_charge(Decimal("100.00"), orders(1, 1, 1))
    assert list(split.values()) == [Decimal("33.34"), Decimal("33.33"), Decimal("33.33")]


def test_zero_weight_load_splits_evenly():
    split = prorate_charge(Decimal("50.00"), orders(0, 0))
    assert list(split.values()) == [Decimal("25.00"), Decimal("25.00")]


def test_prorate_by_pallets_and_credits():
    load = [Order("A", 9000, pallets=6), Order("B", 1000, pallets=2)]
    assert prorate_charge(Decimal("-80.00"), load, by="pallets") == {"A": Decimal("-60.00"), "B": Decimal("-20.00")}
    with pytest.raises(ValueError):
        prorate_charge(Decimal("80.00"), load, by="volume")

